// 4 slots, 3.5h apart. Longest seeded movie is 171 min (+15 min gap) so they never overlap.
const SLOTS = ['10:00', '13:30', '17:00', '20:30'];
const DAYS = 5;

function localDateStr(d) {
  // YYYY-MM-DD in the cinema timezone
  const [sign, hh, mm] = /([+-])(\d{2}):(\d{2})/.exec(TZ_OFFSET).slice(1);
  const offsetMs = (sign === '-' ? -1 : 1) * (Number(hh) * 60 + Number(mm)) * 60000;
  return new Date(d.getTime() + offsetMs).toISOString().slice(0, 10);
}

// Builds show documents for the next DAYS days, skipping slots already gone
// and slots where that screen already has a show nearby (so it never overlaps
// shows an admin created, and never duplicates on a re-run).
function buildShows(movieDocs, theatreDocs, existing = []) {
  const now = new Date();
  const busy = existing.map((s) => `${s.theatre}|${s.screenName}|${Math.floor(s.startTime.getTime() / (3 * 3600e3))}`);
  const taken = new Set(busy);
  const shows = [];
  let k = 0;
  for (let day = 0; day < DAYS; day++) {
    const dateStr = localDateStr(new Date(now.getTime() + day * 86400000));
    for (const t of theatreDocs) {
      for (const screen of t.screens) {
        for (const slot of SLOTS) {
          const startTime = new Date(`${dateStr}T${slot}:00${TZ_OFFSET}`);
          const movie = movieDocs[k++ % movieDocs.length];
          if (startTime <= now) continue; // slot already gone today
          const near = [-1, 0, 1].some((d) =>
            taken.has(`${t._id}|${screen.name}|${Math.floor(startTime.getTime() / (3 * 3600e3)) + d}`)
          );
          if (near) continue;
          shows.push({
            movie: movie._id,
            theatre: t._id,
            screenName: screen.name,
            rows: screen.rows,
            seatsPerRow: screen.seatsPerRow,
            startTime,
            price: slot === '20:30' ? 280 : slot === '10:00' ? 160 : 220,
            bookedSeats: [],
          });
        }
      }
    }
  }
  return shows;
}

// Full reset: WIPES everything and inserts demo data.
async function seed({ log = console.log } = {}) {
  await Promise.all([User.deleteMany(), Movie.deleteMany(), Theatre.deleteMany(), Show.deleteMany(), Booking.deleteMany()]);
  await Show.syncIndexes();

  // .create() (not insertMany) so the bcrypt pre-save hook runs.
  await User.create({ name: 'Admin', email: 'admin@imovies.com', password: 'admin123', role: 'admin' });
  await User.create({ name: 'Demo User', email: 'user@imovies.com', password: 'user123' });
  await User.create({ name: 'Second User', email: 'user2@imovies.com', password: 'user123' });

  const now = new Date();
  const movieDocs = await Movie.insertMany(
    movies.map((m, i) => ({
      ...m,
      posterUrl: `/posters/${m.title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}.svg`,
      releaseDate: new Date(now.getTime() - i * 6 * 86400000),
    }))
  );
  const theatreDocs = await Theatre.insertMany(theatres);
  const shows = buildShows(movieDocs, theatreDocs);
  await Show.insertMany(shows);

  log(`Seeded: 3 users, ${movieDocs.length} movies, ${theatreDocs.length} theatres, ${shows.length} shows`);
  log('  admin@imovies.com / admin123   (admin)');
  log('  user@imovies.com  / user123    (user)');
  log('  user2@imovies.com / user123    (second user, to test seats from another account)');
}

// Keeps existing users, bookings and booked seats. Only adds shows for the
// coming days so a long-lived database never runs out of showtimes.
async function topUpShows({ log = console.log } = {}) {
  const [movieDocs, theatreDocs, existing] = await Promise.all([
    Movie.find(),
    Theatre.find(),
    Show.find({ startTime: { $gte: new Date(Date.now() - 6 * 3600e3) } }, 'theatre screenName startTime'),
  ]);
  if (!movieDocs.length || !theatreDocs.length) return 0;
  const shows = buildShows(movieDocs, theatreDocs, existing);
  if (shows.length) await Show.insertMany(shows);
  log(`Added ${shows.length} new show(s) for the next ${DAYS} days`);
  return shows.length;
}

module.exports = seed;
module.exports.seed = seed;
module.exports.topUpShows = topUpShows;
